/// The session's v2 order client id session: untagged, already 5 ids into its life.
const SESSION: &str = "W00000000abcd";
const ALT: &str = "sim#ALT";

/// The label of [`ALT`].
fn alt() -> AccountLabel {
    AccountLabel::parse("ALT").expect("a label")
}

/// Which reports a case looks for.
type ReportPick = Box<dyn Fn(&ExecutionReport) -> bool>;
/// A segment's header, before its first frame (`vike_journal`'s `format::HEADER`).
const HEADER: usize = 16;

/// A sim/BTCUSDT engine refusing an order over 10 000 notional, on the default account or `route_key`'s, holding a
/// mark of 100 (a `Snapshot` carries marks, so a replay of it has one: no decision of the session is priced at a mark
/// the replay lacks).
fn engine(route_key: Option<&str>) -> Engine<RecordingClient> {
    let mut engine = unmarked_engine();
    engine.account.set_mark_from("sim", "BTCUSDT", 100.0, MarkSource::VenueMark, 0);
    if let Some(key) = route_key {
        engine.route_key = key.to_string();
    }
    engine
}

/// [`engine`] holding no mark.
fn unmarked_engine() -> Engine<RecordingClient> {
    let limits = RiskLimits { max_notional_per_order: Some(10_000.0), ..RiskLimits::new() };
    Engine::new(
        Account::new(1.0, "sim", None, BalanceMode::Delta),
        RiskGate::new(limits),
        RecordingClient::default(),
        "sim",
        "BTCUSDT",
    )
}

/// A mount on sim/BTCUSDT's `account` that rests one bid on its first quote, minting under strategy code `code`.
fn bidder(code: &str, account: AccountLabel, id: &str) -> Mount {
    Mount {
        order_client_id_code: OrderClientIdStrategyCode::parse(code),
        // named: on a venue of two accounts an order naming none is refused as ambiguous
        account: Some(account),
        symbols: Vec::new(),
        controller_id: Some(id.into()),
        underlying_symbol: None,
        venue: "sim".into(),
        symbol: "BTCUSDT".into(),
        interval: "1m".into(),
        strategy: Box::new(RestOnce { done: Arc::default() }),
    }
}

fn fill(order_client_id: &str, trade_id: &str, qty: f64) -> Event {
    Event::Fill(FillEvent {
        trade_id: TradeId::new(trade_id).expect("non-empty"),
        order_client_id: order_client_id.into(),
        venue: "sim".into(),
        symbol: "BTCUSDT".into(),
        side: 1,
        last_qty: qty,
        last_price: 100.0,
        commission: 0.01,
        commission_asset: "USDT".into(),
        liquidity_side: "taker".into(),
        timestamp: 7,
        mark_price: None,
        position_side: PositionSide::Both,
    })
}

fn ringed(event: Event, ring: &str, sequence: u64) -> GatewayEvent {
    GatewayEvent {
        event,
        route_key: ring.into(),
        cursor: EventRingCursor { gateway_epoch: 1, sequence, timestamp_ms: sequence as i64 },
    }
}

fn accepted(order_client_id: &str, venue_order_id: &str) -> Event {
    Event::OrderAccepted(OrderAccepted {
        order_client_id: order_client_id.into(),
        venue_order_id: Some(venue_order_id.into()),
        timestamp: 5,
    })
}

/// The id `session` minted at `seq` for strategy code `code`, full shape, account `#3`.
fn minted(session: &str, seq: u64, code: &str) -> String {
    let mut g = OrderClientIdGenerator::resume(session.into(), seq);
    let plan = OrderClientIdPlan::new(OrderClientIdShape::FULL, OrderClientIdAccountCode::of_id(3));
    let labels = OrderClientIdLabels::new(
        OrderClientIdSource::Strategy,
        OrderClientIdStrategyCode::parse(code).expect("a code"),
        OrderClientIdIntent::OpenLong,
    );
    plan.mint(&mut g, labels)
}

/// **The scripted session**: two accounts (`sim`, `sim#ALT`) with a mount each resting a bid, an operator order on
/// each, their lifecycles over plain and ringed events, a fee correction, an amend, a cancel, a late fill after it
/// and a deny, a `Snapshot` every 4 records.
fn run_session(dir: &Path) {
    let config = CoreConfig {
        order_client_id_session: Some((SESSION.into(), 5)),
        strategy: Some(bidder("0001", AccountLabel::Default, "bidder-a")),
        extra_mounts: vec![bidder("0002", alt(), "bidder-b")],
        ..journaled_config(dir, 1_000_000.0, 4)
    };
    let handle = spawn_core_multi(engine(None), vec![(1_000_000.0, engine(Some(ALT)))], config);
    let cell = handle.snapshot_cell();
    // the core's own words when a wait runs out
    let wait_for_orders = |n: usize, what: &str| {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while cell.load_full().orders.len() != n {
            let s = cell.load_full();
            assert!(
                std::time::Instant::now() < deadline,
                "{what}: orders {:?}, recent events {:#?}",
                s.orders.iter().map(|o| &o.order_client_id).collect::<Vec<_>>(),
                s.recent_events
            );
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
    };
    handle.tick_sender().quote(sim_quote(100.0, 1)).unwrap();
    wait_for_orders(2, "both mounts' bids rest");
    let bid_of = |code: &str| {
        let code = OrderClientIdStrategyCode::parse(code);
        cell.load_full()
            .orders
            .iter()
            .map(|o| o.order_client_id.clone())
            .find(|id| {
                matches!(parse_order_client_id(id), Some(OrderClientIdReading::V2(p)) if Some(p.strat) == code)
            })
            .expect("the mount's bid")
    };
    let bid_a = bid_of("0001");
    // every order names its account: on a venue of two accounts one naming none is refused as ambiguous
    let submit = |account: AccountLabel, request: OrderRequest| {
        let request = OrderRequest { account: Some(account), ..request };
        handle.send_command(Command::Order(OrderIntent::Submit(Box::new(request))))
    };
    submit(AccountLabel::Default, sim_limit("op1", 1, 2.0, 100.0));
    submit(alt(), sim_limit("op2", -1, 1.0, 101.0));
    wait_for_orders(4, "both operator orders");
    let events = handle.event_sender();
    let send = |e: Event| events.blocking_send(e).unwrap();
    let ring = |g: GatewayEvent| events.blocking_send_gateway(g).unwrap();
    send(Event::OrderSubmitted(OrderSubmitted { order_client_id: "op1".into(), timestamp: 4 }));
    send(accepted("op1", "V1"));
    send(Event::OrderSubmitted(OrderSubmitted { order_client_id: bid_a.clone(), timestamp: 4 }));
    send(accepted(&bid_a, "VA"));
    ring(ringed(accepted("op2", "V2"), ALT, 1));
    ring(ringed(fill("op1", "f1", 0.5), "sim", 1));
    send(Event::FeeAdjustment(FeeAdjustmentEvent {
        trade_id: TradeId::new("f1").expect("non-empty"),
        order_client_id: "op1".into(),
        venue: "sim".into(),
        symbol: "BTCUSDT".into(),
        last_price: 100.0,
        extra_commission: 0.02,
        commission_asset: "USDT".into(),
        timestamp: 8,
    }));
    handle.send_command(Command::Order(OrderIntent::Modify {
        order_client_id: "op1".into(),
        new_qty: None,
        new_price: Some(99.0),
        new_trigger_price: None,
    }));
    send(Event::OrderModified(OrderModified {
        order_client_id: "op1".into(),
        venue_order_id: None,
        new_qty: None,
        new_price: Some(99.0),
        new_trigger_price: None,
        timestamp: 9,
    }));
    ring(ringed(fill(&bid_a, "fa", 1.0), "sim", 2));
    send(Event::OrderCanceled(OrderCanceled {
        order_client_id: "op1".into(),
        reason: "by hand".into(),
        timestamp: 10,
        post_only_would_cross: false,
        refusal_id: None,
    }));
    send(fill("op1", "f2", 0.25));
    submit(AccountLabel::Default, sim_limit("big", 1, 1_000.0, 100.0));
    ring(ringed(fill("op2", "f3", 1.0), ALT, 2));
    handle.shutdown_and_join();
}

/// The one segment of the journal at `dir`.
fn only_segment(dir: &Path) -> PathBuf {
    let segments: Vec<PathBuf> = std::fs::read_dir(dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|x| x == "vjl"))
        .collect();
    let [segment] = segments.as_slice() else { panic!("one segment: {segments:?}") };
    segment.clone()
}

/// The offset just past each frame of a segment's `bytes` (`[length][check][payload]` after the header).
fn frame_ends(bytes: &[u8]) -> Vec<usize> {
    let (mut ends, mut at) = (Vec::new(), HEADER);
    while at + 8 <= bytes.len() {
        let len = u32::from_le_bytes(bytes[at..at + 4].try_into().unwrap()) as usize;
        if len == 0 {
            break;
        }
        at += 8 + len;
        ends.push(at);
    }
    ends
}

/// The journal at `src` as a crash after its first `k` frames leaves it, at `dst`: every byte past the k-th frame
/// zeroed (a clean end), and nothing else (no durable copy, which would mend the cut).
fn cut_copy(src: &Path, dst: &Path, k: usize) {
    let segment = only_segment(src);
    let mut bytes = std::fs::read(&segment).unwrap();
    let at = if k == 0 { HEADER } else { frame_ends(&bytes)[k - 1] };
    bytes[at..].fill(0);
    std::fs::create_dir_all(dst).unwrap();
    std::fs::write(dst.join(segment.file_name().unwrap()), bytes).unwrap();
}

fn restore(dir: &Path, tmp: &Path) -> RestoreReport {
    restore_recorded(dir, tmp, &[])
}

/// [`restore`] with this install's recorded order client id sessions (`vike.db`'s rows, as the tradehub passes them).
fn restore_recorded(dir: &Path, tmp: &Path, past_sessions: &[(String, u64)]) -> RestoreReport {
    restore_for_boot(Some(&journal_at(dir, 1 << 20, 1_000)), tmp, 1_000_000, past_sessions)
        .expect("readable")
}

/// The next process: `restore` applied to a core over `dir` with the session's two engines and no mount, run and
/// stopped. Returns the journal it leaves.
fn boot(dir: &Path, restore: RestoreReport) -> Vec<JournalRecord> {
    let mut config = journaled_config(dir, 1_000_000.0, 1_000);
    restore.apply_to(&mut config);
    let handle = spawn_core_multi(engine(None), vec![(1_000_000.0, engine(Some(ALT)))], config);
    handle.shutdown_and_join();
    records(dir)
}

/// `JournalRecord` has no `==`: two records are the same when they serialize the same.
fn same(a: &[JournalRecord], b: &[JournalRecord]) -> bool {
    let json = |r: &[JournalRecord]| serde_json::to_string(r).unwrap();
    json(a) == json(b)
}

/// A small segment for a journal written by hand (the default allocates 64 MiB).
fn small_file() -> vike_journal::JournalFileConfig {
    vike_journal::JournalFileConfig { segment_bytes: 1 << 20, flush_every: 8 }
}

/// A sim engine holding `order_client_id` registered (a 1.0 buy at 100.0), as a `Snapshot` would carry it.
fn holding(order_client_id: &str) -> EngineSnapshot {
    let mut engine = sim_engine();
    let mut outbox = vike_execution::EventBusOutbox::default();
    engine.submit_order(&sim_limit(order_client_id, 1, 1.0, 100.0), 1, &mut outbox);
    engine.snapshot_state()
}

fn reports(recs: &[JournalRecord]) -> Vec<ExecutionReport> {
    recs.iter()
        .filter_map(|r| match r {
            JournalRecord::ExecutionReport { report, .. } => Some(report.clone()),
            _ => None,
        })
        .collect()
}

/// The `(after_sequence, through_sequence, order_client_ids, reason)` of every unverified record of `recs`.
fn unverified(recs: &[JournalRecord]) -> Vec<(u64, u64, Vec<String>, String)> {
    recs.iter()
        .filter_map(|r| match r {
            JournalRecord::ExecutionReportsUnverified {
                after_sequence,
                through_sequence,
                order_client_ids,
                reason,
                ..
            } => {
                Some((*after_sequence, *through_sequence, order_client_ids.clone(), reason.clone()))
            }
            _ => None,
        })
        .collect()
}

fn keyed(reports: Vec<ExecutionReport>) -> BTreeMap<(u64, String), Vec<ExecutionReport>> {
    let mut by_key: BTreeMap<(u64, String), Vec<ExecutionReport>> = BTreeMap::new();
    for r in reports {
        by_key.entry((r.caused_by_sequence, r.order_client_id.clone())).or_default().push(r);
    }
    by_key
}

/// **What a boot after a crash at frame `k` must end with**: every report of the uncut run whose cause survived the
/// cut, field for field (a report carries no sequence of its own), unless an unverified record covers its cause,
/// where only the ones written before the crash remain; and no report the uncut run did not write.
fn assert_ends_with_the_uncut_reports(uncut: &[JournalRecord], booted: &[JournalRecord], k: usize) {
    let cut = k.checked_sub(1).map(|i| record_sequence(&uncut[i]));
    let expected = keyed(
        reports(uncut)
            .into_iter()
            .filter(|r| cut.is_some_and(|c| r.caused_by_sequence <= c))
            .collect(),
    );
    let got = keyed(reports(booted));
    let windows = unverified(booted);
    for (key, want) in &expected {
        let have = got.get(key).cloned().unwrap_or_default();
        let covered =
            windows.iter().any(|(after, through, _, _)| key.0 > *after && key.0 <= *through);
        if covered {
            assert!(want.starts_with(&have), "cut {k}, {key:?}: only the written ones: {have:#?}");
        } else {
            assert_eq!(&have, want, "cut {k}, {key:?}: regenerated field for field");
        }
    }
    for key in got.keys() {
        assert!(
            expected.contains_key(key),
            "cut {k}: {key:?} is a report the uncut run never wrote"
        );
    }
}

/// **Record order**: past the cut prefix, the boot journals the unverified record, then the owed reports, and only
/// then any `Snapshot` or the boot's `PositionSnapshot` (whose books hold what the owed reports state).
fn assert_owed_first(booted: &[JournalRecord], k: usize) {
    let rest = &booted[k..];
    let snap = rest.iter().position(|r| {
        matches!(r, JournalRecord::Snapshot { .. } | JournalRecord::PositionSnapshot { .. })
    });
    let owed_end = snap.unwrap_or(rest.len());
    assert!(
        rest[..owed_end].iter().all(|r| matches!(
            r,
            JournalRecord::ExecutionReport { .. }
                | JournalRecord::ExecutionReportsUnverified { .. }
        )),
        "cut {k}: the boot writes what is owed before anything else: {:#?}",
        &rest[..owed_end]
    );
    assert!(
        rest[owed_end..].iter().all(|r| !matches!(
            r,
            JournalRecord::ExecutionReport { .. }
                | JournalRecord::ExecutionReportsUnverified { .. }
        )),
        "cut {k}: nothing owed after the boot Snapshot or the position snapshot"
    );
}

/// **EVERY CUT POINT ENDS WITH THE UNCUT RUN'S REPORTS.** The scripted session, cut after each of its frames in turn:
/// after the boot, the reports keyed by `(caused_by_sequence, order_client_id)` equal the uncut run's with a cause at
/// or before the cut, field for field, or an unverified record names the window (a cut before the first `Snapshot`,
/// with no checkpoint to refold from). A restore that refolded owes no unverified record (no watchdog tick, every
/// order in the base), and what is owed comes before the boot `Snapshot`.
#[test]
fn every_cut_point_ends_with_the_uncut_runs_reports() {
    let uncut_dir = Scratch::reserved("report-crash-uncut");
    let root = Scratch::created("report-crash-cuts");
    let tmp = Scratch::created("report-crash-cuts-tmp");
    run_session(&uncut_dir);
    let uncut = records(&uncut_dir);
    assert!(reports(&uncut).len() >= 15, "the session reports enough: {:#?}", reports(&uncut));
    let mut regenerated = 0;
    for k in 0..=uncut.len() {
        let dir = root.join(format!("cut-{k}"));
        cut_copy(&uncut_dir, &dir, k);
        let restored = restore(&dir, &tmp);
        let refolded = *restored.outcome() == RestoreOutcome::Full;
        regenerated += restored.owed_execution_reports().reports.len();
        if refolded {
            assert_eq!(
                restored.owed_execution_reports().unverified,
                None,
                "cut {k}: a refold that saw everything owes no unverified record"
            );
        }
        let booted = boot(&dir, restored);
        assert!(same(&booted[..k], &uncut[..k]), "cut {k}: the prefix is kept as written");
        assert_owed_first(&booted, k);
        assert_ends_with_the_uncut_reports(&uncut, &booted, k);
    }
    assert!(regenerated > 0, "some cut owed a regenerated report");
}

/// Where a report of the uncut run sits, and its cause.
fn report_at(
    uncut: &[JournalRecord],
    pick: impl Fn(&ExecutionReport) -> bool,
) -> (usize, ExecutionReport) {
    uncut
        .iter()
        .enumerate()
        .rev()
        .find_map(|(i, r)| match r {
            JournalRecord::ExecutionReport { report, .. } if pick(report) => {
                Some((i, report.clone()))
            }
            _ => None,
        })
        .expect("the session wrote such a report")
}

fn status_is(report: &ExecutionReport, status: OrderStatus) -> bool {
    report.fill.is_none() && report.order.as_ref().is_some_and(|o| o.status == status)
}

/// **A REPORT A CRASH CUT OFF IS JOURNALED AT THE NEXT BOOT**, one case per cause kind (a fill, a fee correction, an
/// accept, a cancel, a registration, a deny): the session cut right after the report's cause, so the cause is durable
/// and the report is not. The boot regenerates it, equal to the one the crash took, and journals it.
#[test]
fn a_report_a_crash_cut_off_is_journaled_at_the_next_boot() {
    let uncut_dir = Scratch::reserved("report-crash-kinds-uncut");
    let root = Scratch::created("report-crash-kinds");
    let tmp = Scratch::created("report-crash-kinds-tmp");
    run_session(&uncut_dir);
    let uncut = records(&uncut_dir);
    let kinds: [(&str, ReportPick); 6] = [
        ("fill", Box::new(|r| r.fill.is_some())),
        ("fee correction", Box::new(|r| r.fee_correction.is_some())),
        ("accept", Box::new(|r| status_is(r, OrderStatus::Accepted))),
        ("cancel", Box::new(|r| status_is(r, OrderStatus::Canceled))),
        ("registration", Box::new(|r| status_is(r, OrderStatus::Initialized))),
        ("deny", Box::new(|r| status_is(r, OrderStatus::Denied))),
    ];
    for (kind, pick) in kinds {
        let (_, lost) = report_at(&uncut, pick);
        let cause = uncut
            .iter()
            .position(|r| record_sequence(r) == lost.caused_by_sequence)
            .expect("its cause is journaled");
        let dir = root.join(kind.replace(' ', "-"));
        cut_copy(&uncut_dir, &dir, cause + 1);
        let restored = restore(&dir, &tmp);
        assert_eq!(*restored.outcome(), RestoreOutcome::Full, "{kind}: {:?}", restored.notes());
        assert!(
            restored.owed_execution_reports().reports.iter().any(|(_, r)| *r == lost),
            "{kind}: regenerated: {:#?}",
            restored.owed_execution_reports()
        );
        let booted = boot(&dir, restored);
        assert!(reports(&booted[cause + 1..]).contains(&lost), "{kind}: journaled again");
    }
}

/// **A LATE FILL ON A SESSION OLDER THAN THE READABLE JOURNAL REGENERATES AS OURS.** The session that minted the id
/// is named by no record of this journal (it ended before it: a journal moved aside, a v1 session); only `vike.db`
/// remembers it, and the live core held it as a past session. A crash cuts the fill's report off: the boot restore,
/// handed the recorded sessions as the tradehub hands them (`restore_for_boot`'s `past_sessions`), regenerates it
/// OURS, field for field, and so does one handed none: the `Snapshot` carries the past sessions its core held
/// (`Snapshot.order_client_id_past_sessions`, decision 0304).
#[test]
fn a_late_fill_on_a_session_older_than_the_journal_regenerates_as_ours() {
    let uncut_dir = Scratch::reserved("report-crash-old-session-uncut");
    let root = Scratch::created("report-crash-old-session");
    let tmp = Scratch::created("report-crash-old-session-tmp");
    let older: (String, u64) = ("Wzzzzzzz00000".into(), 3);
    let config = CoreConfig {
        order_client_id_session: Some((SESSION.into(), 5)),
        order_client_id_past_sessions: vec![older.clone()],
        // a `Snapshot` after every record: the base a refold starts from, before the late fill
        ..journaled_config(&uncut_dir, 1_000_000.0, 1)
    };
    let handle = spawn_core_multi(engine(None), vec![(1_000_000.0, engine(Some(ALT)))], config);
    let events = handle.event_sender();
    events.blocking_send(fill("EXT-0", "warm", 1.0)).unwrap();
    let late = minted(&older.0, 2, "0003");
    events.blocking_send_gateway(ringed(fill(&late, "late", 1.0), "sim", 1)).unwrap();
    handle.shutdown_and_join();

    let uncut = records(&uncut_dir);
    let (_, lost) = report_at(&uncut, |r| r.order_client_id == late);
    assert_eq!(lost.ownership, ExecutionOwnership::Ours, "live, the recorded session made it ours");
    assert!(
        uncut.iter().all(|r| !matches!(r, JournalRecord::Snapshot { order_client_id_session, .. }
            if *order_client_id_session == older.0)),
        "no record of this journal names the older session"
    );
    let cause = uncut
        .iter()
        .position(|r| record_sequence(r) == lost.caused_by_sequence)
        .expect("its cause is journaled");
    let dir = root.join("cut");
    cut_copy(&uncut_dir, &dir, cause + 1);
    let regenerated = |restored: &RestoreReport| -> Vec<ExecutionReport> {
        let owed = &restored.owed_execution_reports().reports;
        owed.iter().map(|(_, r)| r.clone()).filter(|r| r.order_client_id == late).collect()
    };
    // Decision 0304: the `Snapshot` carries the past sessions its core held, so even a boot handed none (a `vike.db`
    // that could not be read) reads the id as ours.
    let without = regenerated(&restore(&dir, &tmp));
    assert_eq!(
        without,
        std::slice::from_ref(&lost),
        "the newest `Snapshot`'s past sessions make it ours"
    );
    let restored = restore_recorded(&dir, &tmp, std::slice::from_ref(&older));
    assert_eq!(*restored.outcome(), RestoreOutcome::Full, "{:?}", restored.notes());
    assert_eq!(regenerated(&restored), [lost], "regenerated OURS, field for field");
}

/// **A PANIC HALT IS JOURNALED, SO A REFOLD DENIES WHAT IT DENIED.** A handler panic halts the live core (safe
/// state), and the next order is DENIED. A replay core does not panic where the live one did, so a refold from the
/// `Snapshot` BEFORE the panic would fold that order as an open one. The halt writes a `Snapshot` of the halted
/// engines, as every trading-state change a replay cannot reproduce does: cut right after the denied order's cause,
/// the boot regenerates it DENIED, or names it unverified, and never as anything else.
#[test]
fn an_order_a_panic_halt_denied_is_never_regenerated_as_open() {
    let uncut_dir = Scratch::reserved("report-crash-panic-uncut");
    let root = Scratch::created("report-crash-panic");
    let tmp = Scratch::created("report-crash-panic-tmp");
    let config = CoreConfig {
        order_client_id_session: Some((SESSION.into(), 5)),
        panic_on_trade_id: Some("boom".into()),
        // a `Snapshot` after every record: there is one before the panic for a refold to start from
        ..journaled_config(&uncut_dir, 1_000_000.0, 1)
    };
    let handle = spawn_core_multi(engine(None), vec![(1_000_000.0, engine(Some(ALT)))], config);
    let cell = handle.snapshot_cell();
    let submit = |id: &str| {
        let request =
            OrderRequest { account: Some(AccountLabel::Default), ..sim_limit(id, 1, 1.0, 100.0) };
        handle.send_command(Command::Order(OrderIntent::Submit(Box::new(request))));
    };
    submit("op1");
    handle.event_sender().blocking_send(fill("op1", "boom", 0.5)).unwrap();
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
    while cell.load_full().fault.is_none() {
        assert!(std::time::Instant::now() < deadline, "the panic never halted the core");
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
    submit("denied1");
    handle.shutdown_and_join();

    let uncut = records(&uncut_dir);
    let (_, denied) = report_at(&uncut, |r| r.order_client_id == "denied1");
    assert!(status_is(&denied, OrderStatus::Denied), "the halt denied it live: {denied:?}");
    let cause = uncut
        .iter()
        .position(|r| record_sequence(r) == denied.caused_by_sequence)
        .expect("its cause is journaled");
    let dir = root.join("cut");
    cut_copy(&uncut_dir, &dir, cause + 1);
    let restored = restore(&dir, &tmp);
    let owed = restored.owed_execution_reports();
    let regenerated: Vec<&ExecutionReport> =
        owed.reports.iter().map(|(_, r)| r).filter(|r| r.order_client_id == "denied1").collect();
    assert!(
        regenerated.iter().all(|r| status_is(r, OrderStatus::Denied)),
        "never regenerated as anything but DENIED: {owed:#?}"
    );
    let named = owed
        .unverified
        .as_ref()
        .is_some_and(|w| w.order_client_ids.iter().any(|id| id == "denied1"));
    assert!(!regenerated.is_empty() || named, "a DENIED report or an unverified entry: {owed:#?}");
    let booted = boot(&dir, restored);
    let journaled: Vec<ExecutionReport> = reports(&booted[cause + 1..])
        .into_iter()
        .filter(|r| r.order_client_id == "denied1")
        .collect();
    assert!(
        journaled.iter().all(|r| status_is(r, OrderStatus::Denied)),
        "the boot journals it DENIED or not at all: {journaled:#?}"
    );
}

/// **A SECOND BOOT OWES NOTHING.** The first boot journals what the crash cut off, and its process dies right after
/// (its exit `Snapshot` never reaches the disk): the next boot finds the regenerated reports written and owes none of
/// them again, and a clean stop owes nothing at all.
#[test]
fn a_second_boot_owes_nothing() {
    let uncut_dir = Scratch::reserved("report-crash-second-uncut");
    let root = Scratch::created("report-crash-second");
    let tmp = Scratch::created("report-crash-second-tmp");
    run_session(&uncut_dir);
    let uncut = records(&uncut_dir);
    let (at, _) = report_at(&uncut, |r| r.fill.is_some());
    let first = root.join("first");
    cut_copy(&uncut_dir, &first, at);
    let restored = restore(&first, &tmp);
    let owed = restored.owed_execution_reports().reports.len();
    assert!(owed > 0, "the cut owes the fill's report");
    let booted = boot(&first, restored);
    assert!(
        restore(&first, &tmp).owed_execution_reports().reports.is_empty(),
        "after a clean stop nothing is owed"
    );
    // the first boot's process dies with what it owed written and its exit `Snapshot` not
    let exit = at
        + booted[at..]
            .iter()
            .position(|r| matches!(r, JournalRecord::Snapshot { .. }))
            .expect("the first boot's exit Snapshot");
    assert!(exit >= at + owed, "what was owed precedes it");
    let second = root.join("second");
    cut_copy(&first, &second, exit);
    let again = restore(&second, &tmp);
    assert_eq!(
        again.owed_execution_reports(),
        &Default::default(),
        "the regenerated reports are written: {:#?}",
        &booted[at..]
    );
}

/// **A TORN REPORT FRAME IS REGENERATED.** The crash tore the report's own frame (its length written, half its
/// payload not): the restore reads the readable prefix (a torn tail, refolded), regenerates the report, and the boot
/// journals it after the live open dropped the torn frame.
#[test]
fn a_torn_report_frame_is_regenerated() {
    let uncut_dir = Scratch::reserved("report-crash-torn-uncut");
    let root = Scratch::created("report-crash-torn");
    let tmp = Scratch::created("report-crash-torn-tmp");
    run_session(&uncut_dir);
    let uncut = records(&uncut_dir);
    let (at, lost) = report_at(&uncut, |r| r.fill.is_some());
    let dir = root.join("torn");
    cut_copy(&uncut_dir, &dir, at + 1);
    let segment = only_segment(&dir);
    let mut bytes = std::fs::read(&segment).unwrap();
    let ends = frame_ends(&bytes);
    let (start, end) = (ends[at - 1], ends[at]);
    bytes[start + 8 + (end - start - 8) / 2..end].fill(0);
    std::fs::write(&segment, bytes).unwrap();

    let restored = restore(&dir, &tmp);
    assert!(
        matches!(restored.outcome(), RestoreOutcome::TornTail { refolded: true, .. }),
        "{:?}",
        restored.outcome()
    );
    let booted = boot(&dir, restored);
    assert!(same(&booted[..at], &uncut[..at]), "the readable prefix is kept");
    assert!(reports(&booted[at..]).contains(&lost), "regenerated: {:#?}", &booted[at..]);
}

/// A journal written by hand: `engines` checkpointed under `session` at `sequence`, then `tail`.
fn hand_journal(
    dir: &Path,
    engines: &[EngineSnapshot],
    session: &str,
    sequence: u64,
    tail: &[Ingest],
) {
    let mut j = Journal::open(dir, small_file()).unwrap();
    let hash = vike_execution::state_hash(engines);
    j.append_snap(10, engines, session, sequence, 0, JournalSnapshotParts::default(), hash)
        .unwrap();
    for (i, message) in tail.iter().enumerate() {
        j.append_command(11 + i as i64, message).unwrap();
    }
    j.flush().unwrap();
}

/// **OWED REPORTS ARE JOURNALED BEFORE THE BOOT SNAPSHOT.** A v1 session's restore switches to a fresh v2 session at
/// assembly, which writes ONE `Snapshot` before the first mint: the report the crash cut off comes before it.
#[test]
fn owed_reports_are_journaled_before_the_boot_snapshot() {
    let dir = Scratch::reserved("report-crash-boot-snap");
    let tmp = Scratch::created("report-crash-boot-snap-tmp");
    hand_journal(
        &dir,
        &[holding("op1")],
        "cafef00d",
        3,
        &[Ingest::Event(accepted("op1", "V1")), Ingest::Event(fill("op1", "f1", 1.0))],
    );
    let restored = restore(&dir, &tmp);
    assert!(!restored.owed_execution_reports().reports.is_empty(), "the fill's at least");
    let mut config = journaled_config(&dir, 1_000_000.0, 1_000);
    restored.apply_to(&mut config);
    let handle = spawn_core_multi(sim_engine(), Vec::new(), config);
    handle.shutdown_and_join();
    let booted = records(&dir);
    let owed: Vec<usize> = booted
        .iter()
        .enumerate()
        .filter(|(_, r)| matches!(r, JournalRecord::ExecutionReport { .. }))
        .map(|(i, _)| i)
        .collect();
    let boot_snap = booted
        .iter()
        .skip(3)
        .position(|r| matches!(r, JournalRecord::Snapshot { .. }))
        .map(|i| i + 3)
        .expect("the session switch writes a boot Snapshot");
    assert_eq!(
        owed,
        (3..3 + owed.len()).collect::<Vec<_>>(),
        "right after the journal's records: {booted:#?}"
    );
    assert!(owed.iter().all(|&i| i < boot_snap));
    let JournalRecord::Snapshot { order_client_id_session, .. } = &booted[boot_snap] else {
        unreachable!()
    };
    assert_ne!(order_client_id_session, "cafef00d", "the boot Snapshot is the switch's");
}

/// **A SNAP-ONLY RESTORE RECORDS THE TAIL AS UNVERIFIED.** A labelled account beside the default one, and a tail
/// whose strategy submit names no engine (a v1 journal from before the route key): the refold is declined, so
/// nothing is regenerated, and the window is ONE unverified record naming the orders its records name.
#[test]
fn a_snap_only_restore_records_the_tail_as_unverified() {
    let dir = Scratch::reserved("report-crash-snap-only");
    let tmp = Scratch::created("report-crash-snap-only-tmp");
    let default = sim_engine().snapshot_state();
    let mut alt = sim_engine().snapshot_state();
    alt.route_key = Some(ALT.into());
    {
        let mut j = Journal::open(&dir, small_file()).unwrap();
        let engines = [default, alt];
        let hash = vike_execution::state_hash(&engines);
        j.append_snap(10, &engines, "cafef00d", 5, 0, JournalSnapshotParts::default(), hash)
            .unwrap();
        let intent = OrderIntent::Submit(Box::new(sim_limit("", 1, 1.0, 100.0)));
        j.append_strategy_submit(11, "m1", &intent, None).unwrap();
        j.append_command(12, &Ingest::Event(fill("op9", "f9", 1.0))).unwrap();
        j.flush().unwrap();
    }
    let restored = restore(&dir, &tmp);
    assert!(
        matches!(restored.outcome(), RestoreOutcome::SnapOnly { .. }),
        "{:?}",
        restored.outcome()
    );
    let owed = restored.owed_execution_reports();
    assert!(owed.reports.is_empty(), "nothing refolded, nothing regenerated");
    let window = owed.unverified.as_ref().expect("the tail is unverified");
    assert_eq!((window.after_sequence, window.through_sequence), (0, 2));
    assert_eq!((window.from_ms, window.to_ms), (Some(11), Some(12)));
    assert_eq!(window.order_client_ids, ["op9"]);
    assert!(window.reason.contains("refolded nothing"), "{}", window.reason);
    let booted = boot(&dir, restored);
    let [(after, through, ids, _)]: [_; 1] = unverified(&booted).try_into().expect("one record");
    assert_eq!((after, through, ids), (0, 2, vec!["op9".to_string()]));
}

/// **A WATCHDOG TICK IN THE CUT WINDOW IS RECORDED AS UNVERIFIED.** The refold drops waker records, so what their
/// sweep decided is not regenerated: the fill after the tick is, and the window is ONE unverified record.
#[test]
fn a_watchdog_tick_in_the_cut_window_is_recorded_as_unverified() {
    let dir = Scratch::reserved("report-crash-waker");
    let tmp = Scratch::created("report-crash-waker-tmp");
    hand_journal(
        &dir,
        &[holding("op1")],
        SESSION,
        5,
        &[Ingest::Watchdog, Ingest::Event(fill("op1", "f1", 1.0))],
    );
    let restored = restore(&dir, &tmp);
    assert_eq!(*restored.outcome(), RestoreOutcome::Full);
    let owed = restored.owed_execution_reports();
    assert!(
        owed.reports.iter().any(|(_, r)| r.fill.is_some()),
        "the fill is regenerated: {owed:#?}"
    );
    let window = owed.unverified.as_ref().expect("the tick's window is unverified");
    assert_eq!((window.after_sequence, window.through_sequence), (0, 2));
    assert!(window.reason.contains("1 watchdog tick"), "{}", window.reason);
}

/// **AN ORDER OUTSIDE THE RESTORE BASE IS NAMED IN THE UNVERIFIED RECORD.** A late fill on an order of ours that ended
/// before the `Snapshot`'s window of ended orders: the refold knows no record of it, so the regenerated report has no
/// order state and no venue order id, and its order is named as unverified.
#[test]
fn an_order_outside_the_restore_base_is_named_in_the_unverified_record() {
    let dir = Scratch::reserved("report-crash-outside-base");
    let tmp = Scratch::created("report-crash-outside-base-tmp");
    let gone = minted(SESSION, 1, "0001");
    hand_journal(
        &dir,
        &[sim_engine().snapshot_state()],
        SESSION,
        5,
        &[Ingest::Event(fill(&gone, "f1", 1.0))],
    );
    let restored = restore(&dir, &tmp);
    let owed = restored.owed_execution_reports();
    let [(_, report)] = owed.reports.as_slice() else { panic!("the late fill: {owed:#?}") };
    assert_eq!(
        (report.ownership, report.order.as_ref(), report.venue_order_id.as_ref()),
        (ExecutionOwnership::Ours, None, None)
    );
    let window = owed.unverified.as_ref().expect("its order is unverified");
    assert_eq!(window.order_client_ids, [gone]);
    assert!(window.reason.contains("outside the restore's base"), "{}", window.reason);
}

/// **AN UNKEYED BASE KEEPS THE RING'S ACCOUNT.** On a base of one default engine the refold folds a gateway event as
/// the plain event it carries, with no ring: the owed report's account is read off its cause record, the ring that
/// carried it, as the live core read it.
#[test]
fn an_unkeyed_base_keeps_the_rings_account() {
    let dir = Scratch::reserved("report-crash-unkeyed");
    let tmp = Scratch::created("report-crash-unkeyed-tmp");
    hand_journal(
        &dir,
        &[sim_engine().snapshot_state()],
        SESSION,
        5,
        &[Ingest::GatewayEvent(Box::new(ringed(fill("EXT-1", "f1", 1.0), ALT, 1)))],
    );
    let restored = restore(&dir, &tmp);
    let owed = restored.owed_execution_reports();
    let [(_, report)] = owed.reports.as_slice() else { panic!("the ringed fill: {owed:#?}") };
    assert_eq!(
        (report.ownership, report.account.as_deref()),
        (ExecutionOwnership::Foreign, Some("ALT")),
        "the ring's account"
    );
}

/// **A LATE FILL ON AN ID OF A SESSION THE JOURNAL SWITCHED FROM IS OURS** in its regenerated report, as it was live:
/// the replay core holds the sessions the newest `Snapshot` names, its own and the past ones its core held
/// (`Snapshot.order_client_id_past_sessions`, decision 0304: the boot no longer reads the older `Snapshot` that named
/// the switched-from session).
#[test]
fn a_late_fill_from_a_session_the_journal_switched_from_is_ours() {
    let dir = Scratch::reserved("report-crash-past-session");
    let tmp = Scratch::created("report-crash-past-session-tmp");
    let past = "Wzzzzzzz00000";
    let engines = [sim_engine().snapshot_state()];
    {
        let mut j = Journal::open(&dir, small_file()).unwrap();
        let hash = vike_execution::state_hash(&engines);
        j.append_snap(10, &engines, past, 3, 0, JournalSnapshotParts::default(), hash).unwrap();
        let switched = [(past.to_string(), 3)];
        let parts = JournalSnapshotParts {
            order_client_id_past_sessions: &switched,
            ..JournalSnapshotParts::default()
        };
        j.append_snap(11, &engines, SESSION, 5, 0, parts, hash).unwrap();
        j.append_command(12, &Ingest::Event(fill(&minted(past, 1, "0001"), "f1", 1.0))).unwrap();
        j.flush().unwrap();
    }
    let restored = restore(&dir, &tmp);
    let owed = restored.owed_execution_reports();
    let [(_, report)] = owed.reports.as_slice() else { panic!("the late fill: {owed:#?}") };
    assert_eq!(report.ownership, ExecutionOwnership::Ours, "{report:?}");
}

/// A journal ending in a frame another build wrote (`ParseFailed`): BROKEN, moved aside.
fn broken_journal(dir: &Path) {
    hand_journal(
        dir,
        &[sim_engine().snapshot_state()],
        SESSION,
        5,
        &[Ingest::Event(fill("op1", "f1", 1.0))],
    );
    let segment = only_segment(dir);
    let payload = br#"{"NotARecordOfThisBuild":{}}"#;
    let mut bytes = std::fs::read(&segment).unwrap();
    let at = *frame_ends(&bytes).last().unwrap();
    let mut frame = (payload.len() as u32).to_le_bytes().to_vec();
    frame.extend_from_slice(&vike_journal::fnv1a32(payload).to_le_bytes());
    frame.extend_from_slice(payload);
    bytes[at..at + frame.len()].copy_from_slice(&frame);
    std::fs::write(&segment, bytes).unwrap();
}

/// **A BROKEN JOURNAL'S CUT WINDOW IS UNVERIFIED.** Nothing is refolded from a journal moved aside, so its records
/// past the last report are ONE unverified record, under the id its stream file gives it, journaled in the fresh one.
#[test]
fn a_broken_journals_window_is_recorded_as_unverified() {
    let root = Scratch::created("report-crash-broken");
    let tmp = Scratch::created("report-crash-broken-tmp");
    let dir = root.join("journal");
    broken_journal(&dir);
    let id = "0123456789abcdef0123456789abcdef";
    let file = serde_json::json!({
        "journal_id": id, "acknowledged_sequence": 0, "acknowledged_ms": 10, "predecessors": []
    });
    std::fs::write(dir.join("execution_stream.json"), file.to_string()).unwrap();
    let restored = restore(&dir, &tmp);
    assert!(
        matches!(restored.outcome(), RestoreOutcome::Broken { moved_to: Some(_), .. }),
        "{:?}",
        restored.outcome()
    );
    let window =
        restored.owed_execution_reports().unverified.clone().expect("the window is unverified");
    assert_eq!(window.journal_id, id);
    assert_eq!((window.after_sequence, window.through_sequence), (0, 1));
    assert_eq!(window.order_client_ids, ["op1"]);
    assert!(window.reason.contains("moved aside broken"), "{}", window.reason);
    let booted = boot(&dir, restored);
    assert_eq!(unverified(&booted).len(), 1, "journaled in the fresh journal: {booted:#?}");
}

/// The JSON of the execution stream file in `dir` (`execution_stream.json`, S1's `JournalExecutionStream`).
fn stream_file(dir: &Path) -> serde_json::Value {
    serde_json::from_slice(&std::fs::read(dir.join("execution_stream.json")).unwrap()).unwrap()
}

/// **A BROKEN JOURNAL IS THE FRESH JOURNAL'S PREDECESSOR.** The journal moved aside keeps its own stream file (one
/// with none gets one, under a fresh id), and the fresh journal's file names it as its predecessor with its path and
/// floor, so the publisher still sends its readable executions; the unverified record is of the moved journal's id.
#[test]
fn a_broken_journal_is_recorded_as_the_fresh_journals_predecessor() {
    for with_stream_file in [true, false] {
        let root = Scratch::created("report-crash-predecessor");
        let tmp = Scratch::created("report-crash-predecessor-tmp");
        let dir = root.join("journal");
        broken_journal(&dir);
        let id = "0123456789abcdef0123456789abcdef";
        if with_stream_file {
            let file = serde_json::json!({
                "journal_id": id, "acknowledged_sequence": 0, "acknowledged_ms": 10, "predecessors": []
            });
            std::fs::write(dir.join("execution_stream.json"), file.to_string()).unwrap();
        }
        let restored = restore(&dir, &tmp);
        let RestoreOutcome::Broken { moved_to: Some(moved), .. } = restored.outcome().clone()
        else {
            panic!("broken: {:?}", restored.outcome())
        };
        let moved_id = stream_file(&moved)["journal_id"].as_str().unwrap().to_string();
        if with_stream_file {
            assert_eq!(moved_id, id, "the moved journal keeps its own file");
        } else {
            assert_eq!(moved_id.len(), 32, "a moved journal with none gets one: {moved_id}");
        }
        let fresh = stream_file(&dir);
        let fresh_id = fresh["journal_id"].as_str().unwrap();
        assert!(fresh_id.len() == 32 && fresh_id != moved_id, "a fresh identity: {fresh}");
        let floor = if with_stream_file { serde_json::json!(0) } else { serde_json::Value::Null };
        assert_eq!(
            fresh["predecessors"],
            serde_json::json!([{
                "journal_id": moved_id,
                "path": moved.to_string_lossy(),
                "acknowledged_sequence": floor,
                "done": false,
            }])
        );
        let window =
            restored.owed_execution_reports().unverified.clone().expect("the window is unverified");
        assert_eq!(window.journal_id, moved_id);
        let booted = boot(&dir, restored);
        assert_eq!(unverified(&booted).len(), 1, "journaled in the fresh journal: {booted:#?}");
    }
}

/// **AN UNREADABLE STREAM FILE STOPS THE BOOT, AND NOTHING IS OVERWRITTEN.** The file holds the journal's id on the
/// execution stream, its floor and the journals moved aside that still owe the datahub. A boot that read it as none
/// moved a broken journal aside and wrote a fresh file over it under a new id, and booted an intact one under no id
/// at all. Both refuse the start now, in words that name the file, and the file, the segment and the directory stay
/// as they were.
#[test]
fn an_unreadable_stream_file_stops_the_boot_and_nothing_is_overwritten() {
    for broken in [true, false] {
        let root = Scratch::created("report-crash-unreadable-stream");
        let tmp = Scratch::created("report-crash-unreadable-stream-tmp");
        let dir = root.join("journal");
        if broken {
            broken_journal(&dir);
        } else {
            let tail = [Ingest::Watchdog, Ingest::Event(fill("op1", "f1", 1.0))];
            hand_journal(&dir, &[holding("op1")], SESSION, 5, &tail);
        }
        let file = dir.join("execution_stream.json");
        let torn = br#"{"journal_id": "0123456789abcdef0123456789abcdef", "predecessors": [{"#;
        std::fs::write(&file, torn).unwrap();
        let segment = std::fs::read(only_segment(&dir)).unwrap();
        let journal = journal_at(&dir, 1 << 20, 1_000);
        let Err(refused) = restore_for_boot(Some(&journal), &tmp, 1_000_000, &[]) else {
            panic!("an unreadable stream file stops the boot (broken: {broken})")
        };
        assert!(refused.contains(&file.display().to_string()), "the file is named: {refused}");
        assert_eq!(std::fs::read(&file).unwrap(), torn, "nothing is written over it");
        assert_eq!(std::fs::read(only_segment(&dir)).unwrap(), segment, "the journal is untouched");
        let names: Vec<String> = std::fs::read_dir(&root)
            .unwrap()
            .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
            .collect();
        assert_eq!(names, ["journal"], "nothing is moved aside (broken: {broken})");
    }
}

/// **A WINDOW IS ALWAYS OF A REAL JOURNAL ID.** An open journal with no stream file yet, whose boot owes an unverified
/// window (a watchdog tick in it), is given its stream file by that boot, under one fresh 32-hex id, and the window
/// carries it: the publisher then streams the journal under that same id, never under an empty name.
#[test]
fn a_journal_with_no_stream_file_takes_its_id_from_the_boot_that_owes_a_window() {
    let dir = Scratch::reserved("report-crash-window-id");
    let tmp = Scratch::created("report-crash-window-id-tmp");
    let tail = [Ingest::Watchdog, Ingest::Event(fill("op1", "f1", 1.0))];
    hand_journal(&dir, &[holding("op1")], SESSION, 5, &tail);
    assert!(!dir.join("execution_stream.json").exists(), "no publisher ever ran here");
    let restored = restore(&dir, &tmp);
    let window = restored.owed_execution_reports().unverified.clone().expect("the tick's window");
    let id = stream_file(&dir)["journal_id"].as_str().unwrap().to_string();
    assert!(
        id.len() == 32 && id.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)),
        "{id}"
    );
    assert_eq!(window.journal_id, id, "the window is of the journal its file names");
    let booted = boot(&dir, restored);
    let journaled: Vec<&str> = booted
        .iter()
        .filter_map(|r| match r {
            JournalRecord::ExecutionReportsUnverified { journal_id, .. } => {
                Some(journal_id.as_str())
            }
            _ => None,
        })
        .collect();
    assert_eq!(journaled, [id.as_str()]);
    let kept = stream_file(&dir)["journal_id"].clone();
    assert_eq!(kept, id.as_str(), "the id the publisher streams under");
}

/// **A DECISION PRICED AT A MARK THE JOURNAL DOES NOT HOLD IS NEVER REGENERATED.** A replay has its checkpoint's marks
/// only, so it may accept what the live core denied (and the order would show as working for ever) or the other way
/// round. The crash cut the report of each submit below; none is regenerated as ACCEPTED or DENIED, each is named in
/// the unverified record instead:
/// - a MARKET order under the notional cap is priced at the mark: the live core read 2 000 (a quote after the
///   checkpoint) and denied 6 BTCUSDT over the 10 000 cap, where the checkpoint's 100 accepts them;
/// - a limit order on the mounted symbol of an engine that holds no mark of its own: the live mark floor
///   (`RiskGate::require_mark`, which a snapshot-built engine never runs) may have denied it.
///
/// A limit order at its own price on a priced engine read nothing of the market, and is regenerated.
#[test]
fn a_deny_decided_on_a_mark_price_is_unverified_never_regenerated() {
    let market = OrderRequest {
        order_type: vike_model::OrderType::Market,
        price: None,
        ..sim_limit("mkt1", 1, 6.0, 100.0)
    };
    let cases = [
        (Some(100.0), market, true),
        (None, sim_limit("lim1", 1, 1.0, 100.0), true),
        (Some(100.0), sim_limit("lim2", 1, 1.0, 100.0), false),
    ];
    for (mark, request, unverifiable) in cases {
        let id = request.order_client_id.clone();
        let dir = Scratch::reserved("report-crash-market-data");
        let tmp = Scratch::created("report-crash-market-data-tmp");
        let mut base = unmarked_engine();
        if let Some(mark) = mark {
            base.account.set_mark_from("sim", "BTCUSDT", mark, MarkSource::VenueMark, 0);
        }
        let submit = Ingest::Command(Command::Order(OrderIntent::Submit(Box::new(request))));
        hand_journal(&dir, &[base.snapshot_state()], SESSION, 5, &[submit]);
        let restored = restore(&dir, &tmp);
        assert_eq!(*restored.outcome(), RestoreOutcome::Full, "{id}: {:?}", restored.notes());
        let owed = restored.owed_execution_reports().clone();
        let regenerated: Vec<&ExecutionReport> =
            owed.reports.iter().map(|(_, r)| r).filter(|r| r.order_client_id == id).collect();
        if unverifiable {
            assert!(
                regenerated.is_empty(),
                "{id}: no ACCEPTED or DENIED is regenerated: {owed:#?}"
            );
            let window = owed.unverified.as_ref().expect("the decision is unverified");
            assert_eq!(window.order_client_ids, std::slice::from_ref(&id));
            assert!(window.reason.contains("market data"), "{id}: {}", window.reason);
        } else {
            assert!(!regenerated.is_empty(), "{id}: regenerated: {owed:#?}");
            assert_eq!(owed.unverified, None, "{id}: nothing to verify");
        }
        let booted = boot(&dir, restored);
        let journaled = reports(&booted).into_iter().filter(|r| r.order_client_id == id).count();
        assert_eq!(journaled == 0, unverifiable, "{id}: {booted:#?}");
        assert_eq!(unverified(&booted).len(), usize::from(unverifiable), "{id}");
    }
}
